import React, { useState, useEffect } from "react";
import { Routes, Route, useNavigate, useLocation } from "react-router-dom";

import LoginForm from "./LoginForm";
import RegisterForm from "./RegisterForm";
import DepositForm from "./DepositForm";
import WithdrawForm from "./WithdrawForm";
import Home from "./Home";
import AdminDepositRequests from "./AdminDepositRequests";
import AdminWithdrawRequests from "./AdminWithdrawRequests";
import UserHistory from "./UserHistory";
import AdminUserHistory from "./AdminUserHistory";
import Match from "./components/Match";
import LudoBoard from "./components/LudoBoard";
import ForgotPassword from "./Forgotpassword";
import PaymentNumber from "./PaymentNumber";
import LifetimeWithdraw from "./pages/LifetimeWithdraw"; // ← নতুন লাইফটাইম উইথড্র থেকে ইম্পোর্ট

function App() {
  // ... আগের কোড একই থাকবে

  // isAdmin চেক এবং বাকি কোড যেমন ছিল

  return (
    <Routes>
      {/* Home */}
      <Route
        path="/"
        element={
          <Home
            token={token}
            mobile={mobile}
            gameId={gameId}
            onLogout={handleLogout}
            onShowDeposit={() => navigate("/deposit")}
            onShowWithdraw={() => navigate("/withdraw")}
            onShowAdminDepositRequests={() => navigate("/admin-deposits")}
            onShowAdminWithdraw={() => navigate("/admin-withdraws")}
            onShowHistory={() => navigate("/history")}
            onShowAdminUserHistory={() => navigate("/admin-user-history")}
            onShowLudoMatch={() => navigate("/match")}
            onShowLudoBoard={() => navigate("/game")}
          />
        }
      />

      {/* Deposit & Withdraw */}
      <Route
        path="/deposit"
        element={<DepositForm token={token} onCancel={() => navigate("/")} />}
      />
      <Route
        path="/withdraw"
        element={<WithdrawForm token={token} onCancel={() => navigate("/")} />}
      />

      {/* Admin Deposit Requests */}
      <Route
        path="/admin-deposits"
        element={
          isAdmin ? (
            <AdminDepositRequests onCancel={() => navigate("/")} />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>❌ অনুমতি নেই</p>
          )
        }
      />

      {/* Admin Withdraw Requests */}
      <Route
        path="/admin-withdraws"
        element={
          isAdmin ? (
            <AdminWithdrawRequests onCancel={() => navigate("/")} />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>❌ অনুমতি নেই</p>
          )
        }
      />

      {/* Lifetime Withdraw (Admin Only) */}
      <Route
        path="/lifetime-withdraw"
        element={
          isAdmin ? (
            <LifetimeWithdraw token={token} />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>
              ❌ অনুমতি নেই (শুধু অ্যাডমিন)
            </p>
          )
        }
      />

      {/* User History */}
      <Route
        path="/history"
        element={<UserHistory onCancel={() => navigate("/")} />}
      />

      {/* Admin User History */}
      <Route
        path="/admin-user-history"
        element={
          isAdmin ? (
            <AdminUserHistory onCancel={() => navigate("/")} />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>❌ অনুমতি নেই</p>
          )
        }
      />

      {/* Ludo Match */}
      <Route
        path="/match"
        element={
          <Match
            userMobile={mobile}
            gameId={gameId}
            onGameStart={(gameInfo) => {
              setGameData(gameInfo);
              navigate("/game");
            }}
          />
        }
      />

      {/* Ludo Board */}
      <Route
        path="/game"
        element={
          gameData || localStorage.getItem("gameId") ? (
            <LudoBoard
              userMobile={mobile}
              game={
                gameData || {
                  id: localStorage.getItem("gameId"),
                  playerId: localStorage.getItem("playerId"),
                  entryFee: localStorage.getItem("entryFee"),
                }
              }
              onCancel={() => navigate("/")}
            />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>❌ কোনো গেম পাওয়া যায়নি।</p>
          )
        }
      />

      {/* Forgot Password */}
      <Route path="/forgot-password" element={<ForgotPassword />} />

      {/* Admin Payment Number */}
      <Route
        path="/payment-number"
        element={
          isAdmin ? (
            <PaymentNumber token={token} role={role} />
          ) : (
            <p style={{ padding: "20px", textAlign: "center" }}>
              ❌ অনুমতি নেই (শুধু অ্যাডমিন)
            </p>
          )
        }
      />
    </Routes>
  );
}

export default App;
